function aftercare(){return `<div class="page">${heading('Po zákroku','Doma začíná další krok k zotavení.','<p>Obecný průvodce domácí péčí. Vždy se řiďte individuální propouštěcí zprávou svého veterináře.</p>')}<div class="aftercare-layout"><div class="care-grid">${[
 ['01','Klidné prostředí','Připravte psovi klidné, bezpečné místo. Pohyb omezte podle pokynů lékaře; zabraňte skákání, běhání a nehlídané aktivitě.'],
 ['02','Léky podle plánu','Dodržujte předepsané dávky a časy. Léčbu sami neměňte a při pochybnostech kontaktujte ošetřujícího veterináře.'],
 ['03','Ochrana rány','Ránu denně kontrolujte a zabraňte olizování či kousání doporučenou ochrannou pomůckou. Přípravky na ránu používejte jen podle pokynů lékaře.'],
 ['04','Kontroly a rehabilitace','Dodržujte plán kontrol. Návrat k zátěži a rehabilitaci zahajte až po domluvě s ošetřujícím týmem.']
 ].map(([n,t,p])=>`<section class="care-card"><span class="care-number">${n}</span><h2>${t}</h2><p>${p}</p></section>`).join('')}</div><aside class="info-panel"><div class="eyebrow">Mějte po ruce</div><h2>Plán pro<br>domácí péči.</h2><ul class="checklist"><li>Propouštěcí zprávu</li><li>Rozpis předepsaných léků</li><li>Termín příští kontroly</li><li>Kontakt na veterináře</li></ul><a class="button outline" href="${withBase('/kontakt/')}">Kontakty kliniky</a></aside></div><section class="urgent-note"><h2>Kdy kontaktovat veterináře</h2><p>Při obtížném dýchání, kolapsu nebo výrazném krvácení vyhledejte ihned veterinární pohotovost. Při zhoršování stavu, silné bolesti, otevření rány, hnisu či zápachu kontaktujte veterináře bez odkladu.</p></section><p class="source-note">Obecné informace podle <a href="https://www.acvs.org/small-animal/postoperative-care-after-surgery-what-animal-owners-should-expect/" target="_blank" rel="noopener">American College of Veterinary Surgeons</a>. Nenahrazují individuální doporučení pro vašeho psa.</p></div>`}

let content,title='Veterinární klinika';const pages={[withBase('/cenik/')]:[pricing,'Ceník'],[withBase('/recenze/')]:[reviews,'Recenze'],[withBase('/po-zakroku/')]:[aftercare,'Po zákroku'],[withBase('/')]: [home,'Veterinární klinika'],[withBase('/o-nas/')]:[about,'O nás'],[withBase('/sluzby/')]:[servicesPage,'Naše služby'],[withBase('/tym/')]:[team,'Náš tým'],[withBase('/technologie/')]:[technologies,'Technologie'],[withBase('/kontakt/')]:[contact,'Kontakt'],[withBase('/galerie/')]:[gallery,'Galerie'],[withBase('/pohotovost/')]:[emergency,'Pohotovost'],[withBase('/caste-dotazy/')]:[faq,'Často kladené otázky'],[withBase('/objednani/')]:[booking,'Objednání']};
if(pages[path]){content=pages[path][0]();title=pages[path][1];}else{const s=services.find(s=>path===withBase('/sluzby/'+s[0]+'/')),p=people.find(p=>path===withBase('/tym/'+p[0]+'/'));if(s){content=serviceDetail(s);title=s[1];}else if(p){content=personDetail(p);title=p[1];}else{content=`<div class="page">${heading('Stránka nenalezena','Tudy cesta nevede.')}<a class="button" href="${withBase('/')}">Zpět na úvod</a></div>`;title='Stránka nenalezena';}}
document.title=`${title} — ATLAS VET`;
document.getElementById('app').innerHTML=header()+`<main id="main">${content}</main>`+footer();
$('.menu-toggle').addEventListener('click',()=>{const open=$('.nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');}});
if(path===withBase('/galerie/')){document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});document.querySelectorAll('[data-photo]').forEach(x=>x.hidden=b.dataset.filter!=='Vše'&&x.dataset.category!==b.dataset.filter);}));const dialog=$('#lightbox');document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{const p=photos[+b.dataset.photo];dialog.querySelector('h2').textContent=p[2];dialog.querySelector('.dialog-photo').innerHTML=art(p[0],p[2]);dialog.showModal();}));dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});}
if(path===withBase('/objednani/')){const form=$('#booking-form');let stage=0;const date=new Date();date.setMinutes(date.getMinutes()-date.getTimezoneOffset());form.elements.date.min=date.toISOString().slice(0,10);const chosen=new URLSearchParams(location.search).get('sluzba');if(services.some(s=>s[0]===chosen))form.elements.service.value=chosen;form.elements.date.addEventListener('change',()=>{const day=new Date(form.elements.date.value+'T12:00:00').getDay();form.elements.date.setCustomValidity(day===0?'V neděli se prosím obraťte na pohotovost. Vyberte jiný den.':'');for(const option of form.elements.time.options){option.disabled=day===6&&option.value&&(+option.value.slice(0,2)<9||+option.value.slice(0,2)>=14);}if(form.elements.time.selectedOptions[0]?.disabled)form.elements.time.value='';});function summary(){const s=services.find(s=>s[0]===form.elements.service.value);return `${s?.[1]||''} · ${form.elements.dog.value} · ${form.elements.date.value?new Date(form.elements.date.value+'T12:00:00').toLocaleDateString('cs-CZ'):''} v ${form.elements.time.value}`;}function show(n,focus=true){stage=n;$('#step-number').textContent=String(n+1);form.querySelectorAll('[data-stage]').forEach((x,i)=>{x.hidden=i!==n;x.querySelectorAll('input,select').forEach(el=>el.disabled=i!==n);});document.querySelectorAll('.step').forEach((x,i)=>(x.classList.toggle('active',i===n),x.setAttribute('aria-current',i===n?'step':'false')));$('#booking-summary').textContent=summary();form.querySelector(`[data-stage="${n}"] h2`).setAttribute('tabindex','-1');if(focus)form.querySelector(`[data-stage="${n}"] h2`).focus({preventScroll:true});}form.querySelectorAll('[data-next]').forEach(b=>b.addEventListener('click',()=>{if(form.reportValidity())show(stage+1);}));form.querySelectorAll('[data-prev]').forEach(b=>b.addEventListener('click',()=>show(stage-1)));form.addEventListener('submit',e=>{e.preventDefault();if(stage<2){if(form.reportValidity())show(stage+1);return;}if(!form.reportValidity())return;$('#result-summary').textContent=summary();form.hidden=true;$('#booking-result').hidden=false;});$('#restart-booking').addEventListener('click',()=>{form.reset();form.hidden=false;$('#booking-result').hidden=true;show(0,false);});show(0,false);}
